const BUILTIN_WARMUPS = [{"name": "下肢退阶热身", "applies": "周一/周三/周五（腿与后链日）", "steps": "1) 仰卧呼吸：鼻吸4秒-停2秒-口呼6秒，5次×2\n2) 仰卧雨刷（髋内外旋）：来回10次×2（腰不扭）\n3) 仰卧臀桥：2×10（余力4）\n4) 坐姿足弓激活：每脚5秒×5×2（不扣脚趾）\n5) 踝背屈靠墙：每侧10–15次×1–2", "notes": "适合髋/足功能差的起步阶段；范围小、求控制"}, {"name": "上肢胸椎/肩胛退阶热身", "applies": "周二/周六（胸/肩/背日）", "steps": "1) 猫牛（胸椎）：10次×2\n2) 泡沫轴胸椎伸展（或卷毛巾）：6–8次×1–2\n3) 高位肩胛俯卧撑：10次×1–2\n4) 弹力带直臂下拉（肩胛下沉/下旋）：12–15次×2\n5) 俯身T+Y（超轻）：T10次+Y8–10次，循环×2\n6) 外旋：每侧12次×1–2；Face Pull：15次×1–2\n7) 空杠卧推：2×10（练肘位与轨迹）", "notes": "重点改善胸椎伸展与肩胛下沉/下旋控制"}, {"name": "执行规则（九阳神功简版）", "applies": "所有训练日", "steps": "余力说明：余力4≈很轻松；余力3≈还能多做3次；余力2≈还能多做2次；余力1≈还能多做1次。\n主项/大动作：动作一乱先减重；增肌期主项常用余力3–4。\n静息心率高5–10或连续2–3天偏高：当天减量5–10%或提前减载。", "notes": "疲劳管理与加重规则"}];
