function parseWarmupItems(text){
  return (text||'').split('\n').map(x=>x.trim()).filter(Boolean).map((line,i)=>{
    let clean=line.replace(/^\d+[\)\.、]\s*/,'').trim();
    let rest=30;
    let duration='';
    let restMatch=clean.match(/(?:休息|间歇|每次休息)\s*(\d{1,3})\s*(?:s|秒)/i);
    if(restMatch) rest=parseInt(restMatch[1]);
    let noRest=clean.replace(/(?:休息|间歇|每次休息)\s*\d{1,3}\s*(?:s|秒)/i,'').trim();
    let name=noRest, sets=1, reps='';
    let timeSet=noRest.match(/^(.+?)\s*[，,]?\s*(?:(\d+)\s*组\s*[x×＊*]\s*)?(\d{1,3})\s*(?:s|秒)(?:\s*[x×＊*]\s*(\d+))?$/i);
    if(timeSet){
      name=timeSet[1].trim();
      if(timeSet[2]){ sets=parseInt(timeSet[2]); duration=parseInt(timeSet[3]); }
      else { duration=parseInt(timeSet[3]); sets=parseInt(timeSet[4]||1); }
      reps='';
    } else {
      let m=noRest.match(/^(.+?)\s*(\d+)\s*(?:组\s*)?[x×＊*]\s*([\d–\-~至]+)(?:\s*次|次呼吸)?(?:\/侧)?$/i);
      if(m){name=m[1].trim(); sets=parseInt(m[2]); reps=m[3];}
      else {
        let r=noRest.match(/(.+?)\s*(\d+)\s*次/); if(r){name=r[1].trim(); reps=r[2];}
        let t=noRest.match(/^(.+?)\s*[，,]?\s*(\d{1,3})\s*(?:s|秒)$/i); if(t){name=t[1].trim(); duration=parseInt(t[2]);}
      }
    }
    return {name:name||('热身项目'+(i+1)),line:clean,sets:sets||1,reps,duration,rest,index:i,isWarmup:true};
  });
}
function warmupRestControlHTML(id,sec){return restControlHTML(id,{min:15,max:120,def:sec||30,label:'热身'});}
function durationControlHTML(id,sec){let v=sec||'';return `<div class="actionCell" id="act_${id}"><div class="actionInner"><input data-field="duration" placeholder="动作倒计时/秒，可空" type="number" step="1" value="${v}"><button class="actionBtn" onclick="startDurationTimer('${id}')">开始动作倒计时</button></div><div class="actionTimer" id="dt_${id}">${v?fmt(parseInt(v)): '--:--'}</div></div>`;}
