      var row=rows[si]; if(!row) return;
      var setVal=function(sel,val){var x=row.querySelector(sel); if(x) {x.value=(val==null?'':val); if(x.type==='range') updateRestLabel(x);}};
      setVal('[data-field="weight"]',st.weight); setVal('[data-field="reps"]',st.reps); setVal('[data-field="rir"]',st.rir); setVal('[data-field="duration"]',st.duration); setVal('input[type=range]',st.rest||30);
