function markNextSetReady(id){
  var row=document.getElementById('row_'+id);
  if(!row) return;
  var next=row.nextElementSibling;
  while(next && !next.classList.contains('setrow')) next=next.nextElementSibling;
  if(!next) return;
  var nid=String(next.id||'').replace(/^row_/,'');
  if(nid) setRestButtonStatus(nid,'nextReady');
}
function showTimerToast(msg){
  var el=document.getElementById('timerToast');
  if(!el) return;
  el.textContent=msg;
  el.classList.add('show');
  clearTimeout(window.__timerToastT);
  window.__timerToastT=setTimeout(function(){el.classList.remove('show');},4200);
}
function playTone(){
  try{
    var AC=window.AudioContext||window.webkitAudioContext;
    if(!AC) return;
    var ctx=new AC();
    var o=ctx.createOscillator(); var g=ctx.createGain();
    o.type='sine'; o.frequency.value=880; g.gain.value=0.0001;
    o.connect(g); g.connect(ctx.destination); o.start();
    g.gain.exponentialRampToValueAtTime(0.16,ctx.currentTime+0.02);
    g.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+0.42);
    o.stop(ctx.currentTime+0.45);
  }catch(e){}
}
function openTimerConfirm(title,body){
  var mask=document.getElementById('timerConfirmMask');
  var t=document.getElementById('timerConfirmTitle');
  var b=document.getElementById('timerConfirmBody');
  if(t) t.textContent=title||'倒计时结束';
  if(b) b.textContent=body||'可以开始下一步。';
  if(mask) mask.classList.add('show');
}
function closeTimerConfirm(){
  var mask=document.getElementById('timerConfirmMask');
  if(mask) mask.classList.remove('show');
}
function notifyTimerDone(title,body){
  try{navigator.vibrate&&navigator.vibrate([220,90,220]);}catch(e){}
  playTone();
  document.title='⏱ '+title;
  showTimerToast(title+'｜'+body);
  openTimerConfirm(title,body);
  try{ if('Notification' in window && Notification.permission==='granted') new Notification(title,{body:body}); }catch(e){}
}
