function parseRirValue(v){
  v=String(v||'').replace('～','-').replace('~','-').replace('至','-').replace('–','-').trim();
  if(!v)return 0;
  if(v.indexOf('-')>=0){var parts=v.split('-');var a=parseFloat(parts[0]);var b=parseFloat(parts[1]);if(!isNaN(a)&&!isNaN(b))return (a+b)/2;}
  var n=parseFloat(v);return isNaN(n)?0:n;
}
function roundToStep(value,step){
  step=parseFloat(step)||2.5;
  if(step<=0)step=2.5;
  return Math.round(value/step)*step;
}
function fmtKg(v){
  if(!isFinite(v))return '--';
  var x=Math.round(v*100)/100;
  return String(x).replace(/\.00$/,'').replace(/(\.\d)0$/,'$1');
}
var lastCalcOneRm=0;
function calcOneRM(){
  var w=parseFloat(document.getElementById('rmWeight').value);
  var reps=parseFloat(document.getElementById('rmReps').value);
  var rir=parseRirValue(document.getElementById('rmRir').value);
  var move=document.getElementById('rmMove').value||'这个动作';
  if(!w||!reps){alert('先填写重量和完成次数。');return;}
  var effectiveReps=reps+rir;
  var one=w*(1+effectiveReps/30);
  lastCalcOneRm=one;
  document.getElementById('rmResult').innerHTML='动作：<b>'+move+'</b><br>折算逻辑：'+fmtKg(w)+'kg × '+reps+'次 + 余力 '+rir+' ≈ '+fmtKg(effectiveReps)+'RM 强度<br>估算 1RM：<b>'+fmtKg(one)+' kg</b>';
}
function copyRmToTarget(){
  if(!lastCalcOneRm){calcOneRM();}
  if(lastCalcOneRm){document.getElementById('targetOneRm').value=fmtKg(lastCalcOneRm);}
}
function calcTargetWeight(){
  var one=parseFloat(document.getElementById('targetOneRm').value);
  var reps=parseFloat(document.getElementById('targetReps').value);
  var rir=parseRirValue(document.getElementById('targetRir').value);
  var step=parseFloat(document.getElementById('roundStep').value)||2.5;
  if(!one||!reps){alert('先填写1RM和目标次数。');return;}
  var effectiveReps=reps+rir;
  var raw=one/(1+effectiveReps/30);
  var rounded=roundToStep(raw,step);
  document.getElementById('targetResult').innerHTML='目标强度：'+reps+'次 + 余力 '+rir+' ≈ '+fmtKg(effectiveReps)+'RM<br>理论重量：<b>'+fmtKg(raw)+' kg</b><br>按 '+step+'kg 取整后：<b>'+fmtKg(rounded)+' kg</b>';
}


