function pad2(n){return String(n).padStart(2,'0');}
function formatEntryLine(e){
  var parts=[];
  if(e.weight) parts.push(e.weight+(e.unit||'kg'));
  if(e.reps) parts.push('×'+e.reps);
  if(e.duration) parts.push(e.duration+'秒');
  if(e.rir) parts.push('RIR '+e.rir);
  if(e.e1rm) parts.push('e1RM '+e.e1rm);
  var body=parts.length?parts.join('｜'):'未填写';
  if(e.segment) return '  第'+(e.round||'-')+'轮 '+e.segment+(e.segmentLabel?(' '+e.segmentLabel):'')+(e.segmentName?('｜'+e.segmentName):'')+'：'+body;
  return '  第'+(e.set||'-')+'组：'+body;
}
function buildBriefText(log){
  log=log||buildWorkoutLogFromCurrent();
  var lines=[];
  lines.push('训练简章｜'+(log.date||''));
  lines.push('#'+((log.planIndex||0)+1)+' '+(log.title||''));
  if(log.stage) lines.push('阶段：'+log.stage);
  lines.push('');
  var groups={};
  (log.entries||[]).forEach(function(e){
    var key=(e.type||'训练')+'｜'+(e.name||'未命名');
    if(!groups[key]) groups[key]=[];
    groups[key].push(e);
  });
  var keys=Object.keys(groups);
  if(!keys.length){
    lines.push('本次暂无填写的组记录。');
  }else{
    keys.forEach(function(k){
      var arr=groups[k];
      var first=arr[0]||{};
      lines.push('【'+(first.type||'训练')+'】'+(first.name||'未命名'));
      if(first.originalName && first.originalName!==first.name) lines.push('原计划：'+first.originalName);
      arr.forEach(function(e){lines.push(formatEntryLine(e));});
      var note=arr.find(function(e){return e.note;});
      if(note&&note.note) lines.push('备注：'+note.note);
      lines.push('');
    });
  }
  if(log.note){lines.push('今日体感/复盘：');lines.push(log.note);lines.push('');}
  var vol=(log.entries||[]).reduce(function(a,e){return a+(parseFloat(e.weight)||0)*(parseFloat(e.reps)||0);},0);
  var top=(log.entries||[]).reduce(function(a,e){return Math.max(a,parseFloat(e.e1rm)||0);},0);
  lines.push('记录组数：'+(log.entries||[]).length+'｜估算总量：'+Math.round(vol)+'｜最高e1RM：'+(Math.round(top*10)/10));
  return lines.join('\n');
}
